    uint32_t magic_number;
    uint32_t version;
    uint32_t interface_count;
    uint32_t reserved;
} config_header_t;

int parse_vm_network_config(unsigned char* config_data, size_t data_len, int* interface_count) {
    if (!config_data || !interface_count) {
        return -1; // 参数错误
    }

    // 检查是否有足够的数据来读取配置头部
    if (data_len < sizeof(config_header_t)) {
        return -2; // 数据长度不足
    }

    // 读取配置头部
    config_header_t* header = (config_header_t*)config_data;

    // 验证魔数
    if (header->magic_number != 0x12345678) {
        return -3; // 魔数不匹配
    }

    // 检查版本号
    if (header->version != 1) {
        return -4; // 版本不支持
    }

    // 检查接口数量是否合理
    if (header->interface_count > 1000) { // 假设最大接口数为1000
        return -5; // 接口数量异常
    }

    // 计算所需的数据长度
    size_t required_len = sizeof(config_header_t) + 
                         (header->interface_count * sizeof(network_interface_t));

    if (data_len < required_len) {
        return -6; // 数据长度不足以包含所有接口配置
    }

    // 解析网络接口配置
    unsigned char* interface_data = config_data + sizeof(config_header_t);
    for (uint32_t i = 0; i < header->interface_count; i++) {
        network_interface_t* net_interface = 
            (network_interface_t*)(interface_data + i * sizeof(network_interface_t));

        // 在这里可以进一步处理每个接口的配置
